export function iso3For(countryName) {
  return NAME_TO_ISO3[String(countryName || '').trim()] || null
}

// Look up the requirement for nationality -> destination (app country names).
// Returns { type: 'home'|'free'|'voa'|'evisa'|'eta'|'required', days } or null.
export function matrixLookup(nationality, destination) {
  const o = iso3For(nationality)
  const d = iso3For(destination)
  if (!o || !d) return null
  const v = MATRIX[o]?.[d]
  if (!v) return null
  if (v === 'h') return { type: 'home', days: null }
  const t = { f: 'free', v: 'voa', e: 'evisa', t: 'eta', r: 'required' }[v[0]]
  const days = v.length > 1 ? parseInt(v.slice(1), 10) : null
  return { type: t, days: Number.isFinite(days) ? days : null }
}
